def leer_archivo(ruta, default=""):
    """Lee un archivo o devuelve default si hay error."""
    try:
        # En esta web, simulamos que siempre falla
        raise FileNotFoundError(f"No se encontró {ruta}")
    except FileNotFoundError:
        print(f"No se encontró {ruta}, devolviendo default")
        return default
    except Exception as e:
        print(f"Error inesperado: {e}")
        return default

