def biseccion(f, a, b, tol=1e-8, max_iter=100):
    if f(a) * f(b) >= 0:
        raise ValueError("Bolzano no se cumple")
    historial = []
    for k in range(max_iter):
        c = (a + b) / 2
        fc = f(c)
        error = (b - a) / 2
        historial.append({
            "k": k,
            "a": a,
            "b": b,
            "c": c,
            "f(c)": fc,
            "error": error
        })
        if abs(fc) < tol or error < tol:
            return c, k, historial
        if f(a) * fc < 0:
            b = c
        else:
            a = c
    raise RuntimeError(f"No convergió en {max_iter} iteraciones")

