import json

def biseccion(f, a, b, tol=1e-8, max_iter=100):
    if f(a) * f(b) >= 0:
        raise ValueError("Bolzano no se cumple")
    for k in range(max_iter):
        c = (a + b) / 2
        if abs(f(c)) < tol or (b - a) / 2 < tol:
            return c, k
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    raise RuntimeError("No convergió")

f = lambda x: x**3 - x - 2
raiz, iters = biseccion(f, 1, 2)

resumen = {
    "metodo": "biseccion",
    "funcion": "x^3 - x - 2",
    "intervalo": [1, 2],
    "tolerancia": 1e-8,
    "raiz": raiz,
    "iteraciones": iters,
    "convergio": True
}

s = json.dumps(resumen, indent=2)
print(s)
